-- Alat ukur multi-item tambahan: token isian bebas di template Objective
-- diganti token {{form:...}} sehingga terapis mengisi lewat pop-up per item.
update public.operational_options
set objective_template = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(objective_template, 'FAAM (.....)%', '{{form:faam}}'), 'WOMAC (.....)', '{{form:womac}}'), 'KOOS (.....)', '{{form:koos}}'), 'Kujala Score (.....)/100', '{{form:kujala}}'), 'Dizziness Handicap Inventory (.....)/100', '{{form:dhi}}'), 'Fatigue Severity Scale (.....)/63', '{{form:fss}}'), 'Chalder Fatigue Scale (.....)/33', '{{form:chalder}}'), 'CAT (.....)/40', '{{form:cat}}'), 'HIT-6 (.....)/78', '{{form:hit6}}'), 'NIHSS (.....)', '{{form:nihss}}'), 'SPPB (.....)/12', '{{form:sppb}}'), 'ICIQ-UI SF (.....)/21', '{{form:iciq}}'), 'Pain Catastrophizing Scale (.....)/52', '{{form:pcs}}'), 'PCS (.....)/52', '{{form:pcs}}'), 'BASDAI (.....)/10', '{{form:basdai}}'), 'BASFI (.....)/10', '{{form:basfi}}'), 'Mini-BESTest (.....)/28', '{{form:minibest}}'), 'SARA (.....)/40', '{{form:sara}}'), 'Braden (.....)', '{{form:braden}}'), 'GCS (.....)', '{{form:gcs}}'), 'Beighton (.....)/9', '{{form:beighton}}'), 'MRC sum score (.....)/60', '{{form:mrcss}}'), 'MRC-SS (.....)/60', '{{form:mrcss}}'), 'Vancouver Scar Scale (.....)/13', '{{form:vss}}'), 'Neuropathy Symptom Score/DN4 (.....)', '{{form:dn4}}'), 'DN4 (.....)', '{{form:dn4}}')
where objective_template is not null;
